export const TRUMPET_FRAME_COUNT = FRAMES.length;

export default function TrumpetNav({
  frame,
  className,
}: {
  frame: number; // 0-based
  className?: string;
}) {
  return (
    <svg
      width="300"
      height="300"
      viewBox="0 0 300 300"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      className={className}
    >
      {FRAMES[frame % FRAMES.length]}
    </svg>
  );
}
